CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','operator','approver')), disabled boolean NOT NULL DEFAULT false);
CREATE TABLE sessions (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 1, reset_at timestamptz NOT NULL);
CREATE TABLE clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE client_members (client_id uuid REFERENCES clients(id), user_id uuid REFERENCES users(id), PRIMARY KEY(client_id,user_id));
CREATE TABLE oauth_states (state_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), client_id uuid NOT NULL REFERENCES clients(id), platform text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), platform text NOT NULL CHECK(platform IN ('meta','google')), credentials text NOT NULL, status text NOT NULL DEFAULT 'connected', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), connection_id uuid NOT NULL REFERENCES connections(id), platform text NOT NULL CHECK(platform IN ('meta','google')), external_id text NOT NULL, name text NOT NULL, currency text NOT NULL, timezone text NOT NULL, UNIQUE(platform,external_id));
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), name text NOT NULL, storage_key text UNIQUE NOT NULL, content_type text NOT NULL, size bigint NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), name text NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_versions (campaign_id uuid REFERENCES campaigns(id), version integer NOT NULL, briefing jsonb NOT NULL, proposal jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(campaign_id,version));
CREATE TABLE approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL, version integer NOT NULL, kind text NOT NULL CHECK(kind IN ('create','activate')), user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(campaign_id,version) REFERENCES campaign_versions(campaign_id,version), UNIQUE(campaign_id,version,kind));
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), campaign_id uuid REFERENCES campaigns(id), version integer, kind text NOT NULL CHECK(kind IN ('create','activate','sync')), status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,version,kind));
CREATE INDEX jobs_claim_idx ON jobs(status,available_at);
CREATE TABLE external_objects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id), version integer NOT NULL, account_id uuid NOT NULL REFERENCES ad_accounts(id), object_key text NOT NULL, external_id text NOT NULL, kind text NOT NULL, delivery_status text NOT NULL DEFAULT 'PAUSED', UNIQUE(campaign_id,version,account_id,object_key));
CREATE TABLE daily_metrics (account_id uuid REFERENCES ad_accounts(id), external_campaign_id text NOT NULL, day date NOT NULL, currency text NOT NULL, timezone text NOT NULL, attribution text NOT NULL, spend numeric(18,6) NOT NULL CHECK(spend>=0), impressions bigint NOT NULL CHECK(impressions>=0), clicks bigint NOT NULL CHECK(clicks>=0), conversions numeric(18,6) NOT NULL CHECK(conversions>=0), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(account_id,external_campaign_id,day,attribution));
CREATE TABLE audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, client_id uuid REFERENCES clients(id), user_id uuid REFERENCES users(id), action text NOT NULL, entity_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_client_idx ON audit_log(client_id,created_at DESC);
